#!/bin/bash
set -e

build() {
    go build -o dgraph-key main.go
}

example_key1() {
    # Example of a type key
    keys=(
        "00000000000000000000046e616d65000000000000000001"
        "00000000000000000000056b6e6f777304000000000000003c"
        "000000000000000000000b6467726170682e747970650202706572736f6e"
        "0000000000000000000006776f726b4174000000000008e31655"
    )
    for key in "${keys[@]}"; do
        echo "Key: $key"
        go run main.go --op=key --key=$key
    done
}

example_kv1() {
    # Example of packed complete posting
    key=000000000000000000000b6467726170682e747970650202706572736f6e
    
    userMeta=8
    echo "Key: $key"
    go run main.go --op=kv --key=$key --value=$val --userMeta=$userMeta
}

example_kv2() {
    # Example of complete posting with both pack and postings
    key=00000000000000000000046e616d65000000000000000001
    val=0a19088002121408ffffffffffffffffff01120500000000001801121a09ffffffffffffffff1205416c69636518092001600168047005
    userMeta=8
    version=6
    echo "Key: $key"
    go run main.go --op=kv --key=$key --value=$val --userMeta=$userMeta --version=$version
}

example_kv3() {
    # Example of complete posting with both pack and postings and `workFrom`` facet
    key="0000000000000000000006776f726b4174000000000008e31655"
    val=""
    userMeta=8
    echo "Key: $key"
    go run main.go --op=kv --key=$key --value=$val --userMeta=$userMeta
}

example_kv4() {
    # Example of Schema
    key=020000000000000000000e6467726170682e6772617068716c
    val=0a10302d6467726170682e6772617068716c121b0a17302d6467726170682e6772617068716c2e736368656d61100912180a14302d6467726170682e6772617068716c2e7869641009
    userMeta=1
    echo "Key: $key"
    go run main.go --op=kv --key=$key --value=$val --userMeta=$userMeta
}

example_key1